class Hospital {}

abstract class Department {}

class EmergencyRoom extends Department {}

class MedicalRecord {}

class Patient {
  + name : string
}

class Staff {}

class MedicalStaff extends Staff {
  + name : string
}

class AdministrativeStaff extends Staff {
  + name : string
}

class Shift {
  + date : date
}

class Admission {
  + date : date
  + discharge : date
}

Hospital "1" *-- "1..*" Department
