Department "1" -- "1..*" Staff
Department "1" -- "0..*" Patient
Patient "1" -- "1" MedicalRecord
Patient "1" *-- "0..*" Admission
Staff "1" -- "0..*" Shift
EmergencyRoom "1" -- "0..*" Shift

@enduml

